def solve_game(n):
    memo = {}
    def get_max_uncovered(state, is_alice_turn):
        state_tuple = tuple(state)
        if (state_tuple, is_alice_turn) in memo:
            return memo[(state_tuple, is_alice_turn)]

        possible_moves = []
        for i in range(n - 1):
            if not state[i] and not state[i+1]:
                possible_moves.append(i)

        if not possible_moves:
            return state.count(False)

        if is_alice_turn:
            best_val = -1
            for move in possible_moves:
                new_state = list(state)
                new_state[move] = True
                new_state[move+1] = True
                val = get_max_uncovered(tuple(new_state), False)
                if val > best_val:
                    best_val = val
            memo[(state_tuple, is_alice_turn)] = best_val
            return best_val
        else:
            best_val = float('inf')
            for move in possible_moves:
                new_state = list(state)
                new_state[move] = True
                new_state[move+1] = True
                val = get_max_uncovered(tuple(new_state), True)
                if val < best_val:
                    best_val = val
            memo[(state_tuple, is_alice_turn)] = best_val
            return best_val

    initial_state = tuple([False] * n)
    return get_max_uncovered(initial_state, True)

